// Mock the PayPal SDK loader.
jest.mock('@paypal/paypal-js', () => ({
  loadScript: jest.fn(),
}));

import { h } from '@stencil/core';
import { newSpecPage } from '@stencil/core/testing';
import { loadScript } from '@paypal/paypal-js';
import { ScPaypalButtons } from '../paypal-buttons';

const loadScriptMock = loadScript as jest.Mock;

/** Flush pending microtasks/timers so un-awaited bootstraps settle. */
const flush = () => new Promise(resolve => setTimeout(resolve, 0));

/** A fake PayPal SDK whose buttons expose their config. */
const makePaypal = () => {
  const buttons = [];
  return {
    FUNDING: { PAYPAL: 'paypal', CARD: 'card' },
    Buttons: jest.fn(config => {
      const button: any = { config, isEligible: () => true, render: jest.fn(() => Promise.resolve()) };
      buttons.push(button);
      return button;
    }),
    buttons,
  };
};

const makePage = async (order: any = { id: 'checkout_1', currency: 'usd', updated_at: 1 }, buttons = ['paypal', 'card']) => {
  return newSpecPage({
    components: [ScPaypalButtons],
    template: () => <sc-paypal-buttons clientId="client-id" merchantId="merchant-id" buttons={buttons} order={order}></sc-paypal-buttons>,
  });
};

const skeleton = page => page.root.shadowRoot.querySelector('sc-skeleton');

describe('paypal-buttons', () => {
  beforeEach(() => {
    jest.clearAllMocks();
  });

  it('renders', async () => {
    const page = await newSpecPage({
      components: [ScPaypalButtons],
      html: `<sc-paypal-buttons></sc-paypal-buttons>`,
    });
    expect(page.root).toMatchSnapshot();
  });

  it('does not tear down when the checkout updates without a currency or reusable change', async () => {
    const paypal = makePaypal();
    loadScriptMock.mockResolvedValue(paypal);
    const page = await makePage();
    await flush();
    await page.waitForChanges();
    expect(loadScriptMock).toHaveBeenCalledTimes(1);

    paypal.buttons[0].config.onInit();
    await page.waitForChanges();
    expect(skeleton(page)).toBeNull();

    (page.root as any).order = { id: 'checkout_1', currency: 'usd', updated_at: 2 };
    await page.waitForChanges();
    await flush();
    expect(loadScriptMock).toHaveBeenCalledTimes(1);
    expect(skeleton(page)).toBeNull();
  });

  it('does not tear down mid-payment when onApprove refreshes the checkout', async () => {
    const paypal = makePaypal();
    loadScriptMock.mockResolvedValue(paypal);
    const page = await makePage({ id: 'checkout_1', currency: 'usd', updated_at: 1, reusable_payment_method_required: false });
    await flush();
    await page.waitForChanges();
    paypal.buttons[0].config.onInit();
    await page.waitForChanges();

    // The onApprove self-fetch shape: new updated_at, same currency, reusable flag now undefined.
    (page.root as any).order = { id: 'checkout_1', currency: 'usd', updated_at: 2 };
    await page.waitForChanges();
    await flush();
    expect(loadScriptMock).toHaveBeenCalledTimes(1);
    expect(skeleton(page)).toBeNull();
  });

  it('re-bootstraps and shows the skeleton when the currency changes', async () => {
    const paypal = makePaypal();
    loadScriptMock.mockResolvedValue(paypal);
    const page = await makePage();
    await flush();
    await page.waitForChanges();
    paypal.buttons[0].config.onInit();
    await page.waitForChanges();
    expect(skeleton(page)).toBeNull();

    (page.root as any).order = { id: 'checkout_1', currency: 'eur', updated_at: 2 };
    await page.waitForChanges();
    expect(skeleton(page)).not.toBeNull();

    await flush();
    await page.waitForChanges();
    expect(loadScriptMock).toHaveBeenCalledTimes(2);
    // Winning bootstrap re-rendered both funding sources.
    expect(paypal.Buttons).toHaveBeenCalledTimes(4);
  });

  it('re-bootstraps when the reusable payment method requirement changes', async () => {
    const paypal = makePaypal();
    loadScriptMock.mockResolvedValue(paypal);
    const page = await makePage({ id: 'checkout_1', currency: 'usd', reusable_payment_method_required: false });
    await flush();
    await page.waitForChanges();
    expect(paypal.buttons[0].config.createOrder).toBeDefined();

    (page.root as any).order = { id: 'checkout_1', currency: 'usd', reusable_payment_method_required: true };
    await page.waitForChanges();
    await flush();
    expect(loadScriptMock).toHaveBeenCalledTimes(2);
    expect(paypal.buttons[2].config.createBillingAgreement).toBeDefined();
  });

  it('ignores a superseded bootstrap', async () => {
    const paypal = makePaypal();
    let resolveFirst;
    let resolveSecond;
    loadScriptMock.mockReturnValueOnce(new Promise(resolve => (resolveFirst = resolve))).mockReturnValueOnce(new Promise(resolve => (resolveSecond = resolve)));
    const page = await makePage();

    (page.root as any).order = { id: 'checkout_1', currency: 'eur', updated_at: 2 };
    await page.waitForChanges();

    // The newer bootstrap finishes first and renders.
    resolveSecond(paypal);
    await flush();
    expect(paypal.Buttons).toHaveBeenCalledTimes(2);

    // The stale bootstrap resolves late and must not render.
    resolveFirst(paypal);
    await flush();
    expect(paypal.Buttons).toHaveBeenCalledTimes(2);
  });

  it('only bootstraps the funding sources in `buttons`', async () => {
    const paypal = makePaypal();
    loadScriptMock.mockResolvedValue(paypal);
    await makePage({ id: 'checkout_1', currency: 'usd' }, ['paypal']);
    await flush();
    expect(paypal.Buttons).toHaveBeenCalledTimes(1);
    expect(paypal.buttons[0].config.fundingSource).toBe('paypal');
  });
});
